fn main() -> Int {
  let temperature = 28;
  let is_sunny = true;
  let is_weekend = false;
  if temperature > 25 && is_sunny {
    io.println("Beach day!");
  }
  if is_weekend || temperature > 30 {
    io.println("Go outside!");
  }
  return 0;
}
